def tag_reading_group_alerts(apps, schema_editor):
    """Reading-group alerts sent before this column existed: title is '<CODE>: your reading group'."""
    SystemNotification = apps.get_model('attendance', 'SystemNotification')
    Course = apps.get_model('attendance', 'Course')
    suffix = ': your reading group'
